package main

import (
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
)

type ProxyRequest struct {
	TargetURL   string            `json:"target_url"`
	Method      string            `json:"method"`
	Headers     map[string]string `json:"headers"`
	Body        string            `json:"body"`
	CallbackID  string            `json:"callback_id"`
	RetryCount  int               `json:"retry_count"`
}

type ProxyResponse struct {
	StatusCode int               `json:"status_code"`
	Headers    map[string]string `json:"headers"`
	Body       string            `json:"body"`
	CallbackID string            `json:"callback_id"`
}

var allowedSchemes = []string{"http", "https"}

func isSchemeAllowed(url string) bool {
	lower := strings.ToLower(url)
	for _, s := range allowedSchemes {
		if strings.HasPrefix(lower, s+"://") {
			return true
		}
	}
	return false
}

// validateHost checks the host doesn't contain obvious bypasses
func validateHost(url string) bool {
	// Block file://, gopher://, dict:// etc
	if !isSchemeAllowed(url) {
		return false
	}
	// Block localhost references in the URL string
	lower := strings.ToLower(url)
	blocked := []string{"localhost", "127.0.0.1", "[::1]", "0.0.0.0"}
	for _, b := range blocked {
		if strings.Contains(lower, b) {
			return false
		}
	}
	return true
}

func proxyHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req ProxyRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	if req.TargetURL == "" {
		http.Error(w, "target_url is required", 400)
		return
	}

	if !validateHost(req.TargetURL) {
		http.Error(w, "URL validation failed", 403)
		return
	}

	method := req.Method
	if method == "" {
		method = "GET"
	}

	client := &http.Client{
		TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
	}

	var bodyReader io.Reader
	if req.Body != "" {
		bodyReader = strings.NewReader(req.Body)
	}

	httpReq, err := http.NewRequest(method, req.TargetURL, bodyReader)
	if err != nil {
		http.Error(w, fmt.Sprintf("Failed to create request: %v", err), 500)
		return
	}

	for k, v := range req.Headers {
		httpReq.Header.Set(k, v)
	}

	resp, err := client.Do(httpReq)
	if err != nil {
		http.Error(w, fmt.Sprintf("Request failed: %v", err), 502)
		return
	}
	defer resp.Body.Close()

	respBody, _ := io.ReadAll(resp.Body)

	respHeaders := make(map[string]string)
	for k := range resp.Header {
		respHeaders[k] = resp.Header.Get(k)
	}

	proxyResp := ProxyResponse{
		StatusCode: resp.StatusCode,
		Headers:    respHeaders,
		Body:       string(respBody),
		CallbackID: req.CallbackID,
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(proxyResp)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte(`{"status":"ok"}`))
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	http.HandleFunc("/proxy", proxyHandler)
	http.HandleFunc("/health", healthHandler)

	fmt.Printf("Starting proxy service on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
